def build(out=DEFAULT):
 out=Path(out);out.mkdir(parents=True,exist_ok=True)
 pack=out/'runner_pack';private=pack/'internal'/OFFICE;research=out/'researcher';downloads=out/'downloads'
 for p in [private,research,downloads,out/'public_preview']:p.mkdir(parents=True,exist_ok=True)
 m={'schema':'office-workspace-v1','offices':{OFFICE:{'name':'Office of the Mayor, Rochester','official':'Janine Kowalczyk','term_start':'2026-08-01','mailbox':'constituent.services@rochester-office.test'}},'files':[],'mailboxes':{OFFICE:[]},'warmup_ids':{OFFICE:[]},'contacts':{OFFICE:[]}}
 def add(path,title,text,rid,author='Office Administration',kind='record',surface='internal',available=DATE):
  if surface=='internal':storage=f'internal/{OFFICE}/{path}'
  else:storage='public/'+available[:10]+'/'+rid+'.txt'
  content=text.strip()+'\n';dest=pack/storage;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
  stamp=datetime.fromisoformat(available).timestamp();os.utime(dest,(stamp,stamp))
  m['files'].append(dict(storage=storage,surface=surface,office_id=OFFICE,path=path,title=title,record_id=rid,author=author,modified=available,available_from=available,kind=kind,sha256=hashlib.sha256(content.encode()).hexdigest()))
 def eml(path,rid,sender,recipient,subject,body,day):
  add(path,subject,f'From: {sender}\nTo: {recipient}\nDate: {day} 2026\nSubject: {subject}\nMessage-ID: <{rid}@rochester-office.test>\n\n{body}',rid,sender)
